# Meeting 5, parts 6 to 8: profitability (with average balances and the DuPont decomposition as the aggregate), market ratios,
# and the decision at the bank with every family together.

# ================================================================ part 6: profitability
opener(6, 'רווחיות: כמה מניב כל שקל, ולמה?', 'שאלת החלק: הרווח גדל ב-33%. אז למה התשואה של נועה על ההון ירדה?',
       ['יחס ראשון: תשואה על הנכסים', 'יחס שני: תשואה על ההון', 'רווח הוא סרט, הון הוא תמונה: יתרה ממוצעת', 'ועכשיו יחד: פירוק דופונט, שלושה גורמים', 'בגיליון, שלוש שאלות, וכרטיס כלי'], 25, art=('coins', 'כמה מניב שקל?'))

ONE('o-p1', 'יחס ראשון: תשואה על הנכסים', 'ב-2027 הרווח הנקי היה 123,200 ש״ח, וסך הנכסים ליום 31.12.2027 היה 337,600. כמה רווח הניב כל שקל של נכסים?',
    ('רווח נקי 2027', '123,200'), '÷', ('סך הנכסים', '337,600'),
    [('ב-2027|123,200 ÷ 337,600', '36.5%', 'תשואה על הנכסים, 2027', ['123,200 חלקי 337,600.', 'התוצאה: 0.365, כלומר 36.5%.']),
     ('ב-2026|92,400 ÷ 221,400', '41.7%', 'תשואה על הנכסים, 2026', ['92,400 חלקי 221,400.', 'התוצאה: 0.417, כלומר 41.7%.'])],
    ['כל שקל של נכסים הניב כ-36 אגורות רווח בשנה. פחות מבשנה הקודמת, אף שהרווח גדל.'], tag='יחס אחד')
ONE('o-p2', 'יחס שני: תשואה על ההון', 'ב-2027 הרווח הנקי היה 123,200 ש״ח, וההון העצמי ליום 31.12.2027 היה 295,600. כמה רווח הניב כל שקל של הבעלים?',
    ('רווח נקי 2027', '123,200'), '÷', ('הון עצמי', '295,600'),
    [('ב-2027|123,200 ÷ 295,600', '41.7%', 'תשואה על ההון, 2027', ['123,200 חלקי 295,600.', 'התוצאה: 0.417, כלומר 41.7%.']),
     ('ב-2026|92,400 ÷ 172,400', '53.6%', 'תשואה על ההון, 2026', ['92,400 חלקי 172,400.', 'התוצאה: 0.536, כלומר 53.6%.'])],
    ['הרווח גדל, אבל התשואה על ההון ירדה. איך? ההון גדל מהר יותר מהרווח: הרווחים נשארו בחברה, בעיקר כמזומן.'], tag='יחס אחד')

_avge = (NV['eq'][0] + NV['eq'][1]) / 2
assert _avge == 234000 and pc(123200 / _avge) == '52.6%' and pc(123200 / ((221400 + 337600) / 2)) == '44.1%'
ONE('o-p3', 'רווח הוא סרט, הון הוא תמונה: יתרה ממוצעת', 'הרווח של 123,200 נצבר לאורך כל 2027, אבל ההון של 295,600 הוא תמונה ביום האחרון, אחרי שכל הרווח כבר נכנס אליו. בתחילת השנה ההון היה 172,400. איך משווים סרט לתמונה?',
    ('הון בתחילת 2027', '172,400'), '↔', ('הון בסוף 2027', '295,600'),
    [('הון ממוצע|(172,400 + 295,600) ÷ 2', '234,000', 'ההון הממוצע של 2027', ['מחברים את היתרה בתחילת השנה ואת היתרה בסוף השנה, ומחלקים ב-2.', 'התוצאה: 234,000. בערך זה ההון שעבד במהלך השנה.']),
     ('תשואה על ההון הממוצע|123,200 ÷ 234,000', '52.6%', 'התשואה על ההון הממוצע, 2027', ['123,200 חלקי 234,000.', 'התוצאה: 0.526, כלומר 52.6%, במקום 41.7% לפי סוף השנה.'])],
    ['לפי ההון הממוצע: 52.6%, לא 41.7%. סוף השנה מקטין את התשואה, כי הוא כבר כולל את כל הרווח. ב-2026 החברה נפתחה ואין יתרת פתיחה, ולכן משווים שנים רק באותה שיטה.'], tag='לעומק')

# ---------------------------------------------------------------- the aggregate: DuPont, three factors whose product is ROE
_DP = [('שיעור רווח נקי', 'רווח נקי חלקי מכירות', 'nm', pc, 'כמה רווח מכל שקל של מכירות'),
       ('מחזור הנכסים', 'מכירות חלקי סך הנכסים', 'at', f2, 'כמה מכירות מכל שקל של נכסים'),
       ('מכפיל ההון', 'סך הנכסים חלקי הון עצמי', 'em', f2, 'כמה נכסים על כל שקל של הבעלים')]
_dprows = ''
for _i, (_n, _how, _k, _fm, _what) in enumerate(_DP):
    _c = lambda y, i=_i, n=_n, how=_how, k=_k, fm=_fm: _calc(2 * i + 1 + y, fm(RT[k][y]), f'{n}, {2026 + y}', [f'{how}.', f'התוצאה: {fm(RT[k][y])}.'], 'up')
    _dprows += f'<tr><td><b>{TX(_n)}</b><br><span class="dpw">{TX(_what)}</span></td><td class="c">{_c(0)}</td><td class="c">{_c(1)}</td></tr>' + ('<tr class="dpx"><td colspan="3">×</td></tr>' if _i < 2 else '')
_dprows += (f'<tr class="tot"><td><b>{TX("תשואה על ההון (ROE)")}</b></td><td class="c">{_calc(7, pc(RT["roe"][0]), "תשואה על ההון, 2026", ["שלושת הגורמים כפול זה בזה.", "התוצאה: " + pc(RT["roe"][0]) + ", בדיוק רווח נקי חלקי הון עצמי."], "up")}</td>'
            f'<td class="c">{_calc(8, pc(RT["roe"][1]), "תשואה על ההון, 2027", ["שלושת הגורמים כפול זה בזה.", "התוצאה: " + pc(RT["roe"][1]) + ", בדיוק רווח נקי חלקי הון עצמי."], "dn2")}</td></tr>')
S('s-dup', 'פירוק דופונט', 'ועכשיו יחד: למה התשואה על ההון ירדה? פירוק דופונט',
  '<div class="anrow"><div class="col"><table class="tbl2 stmt hor anx dup"><tr><th>קפה נועה</th><th>2026</th><th>2027</th></tr>' + _dprows + '</table>'
  + ('<p class="fhint">' + TX('כל לחיצה חושפת גורם אחד. לחצו על מספר כדי לראות איך חושב.') + '</p>' if MODE == 'deck' else '') + '</div>'
  + '<div class="col">' + DEF('פירוק דופונט (DuPont analysis)', 'התשואה על ההון היא מכפלה של שלושה גורמים: רווחיות המכירות, יעילות הנכסים ומינוף. כשהיא משתנה, הפירוק מראה איזה גורם הזיז אותה.', '20.5% כפול 1.78 כפול 1.14: 41.7%.', n=9, trm='dupont')
  + BAND('dg', 'שיעור הרווח עלה. אבל מחזור הנכסים ירד (מזומן שלא עובד) ומכפיל ההון ירד (פחות חוב). שני אלה הורידו את התשואה.', 10) + '</div></div>', kick='חלק 6 · מצרפים')

RULE('s-prof', 'הכלל: יחסי רווחיות', [
    ('תשואה על הנכסים (Return on Assets, ROA)', 'רווח נקי חלקי סך הנכסים.', '2027: 123,200 חלקי 337,600, כלומר 36.5%.', 'roa'),
    ('תשואה על ההון (Return on Equity, ROE)', 'רווח נקי חלקי ההון העצמי.', '2027: 123,200 חלקי 295,600, כלומר 41.7%.', 'roe'),
    ('יתרה ממוצעת (Average balance)', 'יתרת הפתיחה ועוד יתרת הסגירה, חלקי 2. משתמשים בה כשמחלקים שורה מדוח רווח והפסד ביתרה מהמאזן.', 'הון ממוצע 2027: 234,000. תשואה: 52.6%.', 'avgb')],
    [('רווח נקי', 'סך הנכסים', '<span class="n">36.5%</span>'), ('רווח נקי', 'הון עצמי', '<span class="n">41.7%</span>'), ('פתיחה ועוד סגירה', '2', '<span class="n">234,000</span>')],
    'ושיעורי הרווח ממפגש 4 (גולמי, תפעולי ונקי, כל אחד חלקי המכירות) הם גם הם יחסי רווחיות. בגיליון נחשב את כולם יחד.')

QT('x-prof', 'רווחיות', 'כל יחסי הרווחיות, ופירוק דופונט, בגיליון', ['למעלה הנתונים של קפה נועה. בשורות 9 עד 16 חשבו לכל שנה את שיעורי הרווח, את שתי התשואות, ואת שלושת הגורמים של דופונט.'],
   'כל יחס: שורה חלקי שורה. בשורה 16: שלושת הגורמים כפול זה בזה, ובודקים שיוצאת התשואה על ההון.',
   RSHEET(_nr(('sales', 'מכירות'), ('cogs', 'עלות המכירות'), ('op', 'רווח תפעולי'), ('ni', 'רווח נקי'), ('ta', 'סך הנכסים'), ('eq', 'הון עצמי')),
          [('שיעור רווח גולמי', '=({c}2-{c}3)/{c}2', 'pct1', 'מכירות פחות עלות המכירות, חלקי מכירות'), ('שיעור רווח תפעולי', '={c}4/{c}2', 'pct1', 'רווח תפעולי חלקי מכירות'),
           ('שיעור רווח נקי', '={c}5/{c}2', 'pct1', 'רווח נקי חלקי מכירות'), ('תשואה על הנכסים', '={c}5/{c}6', 'pct1', 'רווח נקי חלקי סך הנכסים'),
           ('תשואה על ההון', '={c}5/{c}7', 'pct1', 'רווח נקי חלקי הון עצמי'), ('מחזור הנכסים', '={c}2/{c}6', 'num2', 'מכירות חלקי סך הנכסים'),
           ('מכפיל ההון', '={c}6/{c}7', 'num2', 'סך הנכסים חלקי הון עצמי'), ('דופונט: שלושת הגורמים', '={c}11*{c}14*{c}15', 'pct1', 'שיעור רווח נקי כפול מחזור הנכסים כפול מכפיל ההון')]),
   one=True, big=True, hints=['שיעור רווח גולמי: =(B2-B3)/B2. דופונט: =B11*B14*B15.'], remind='=B11*B14*B15', done='2027: תשואה על ההון 41.7%, ודופונט נותן בדיוק אותו מספר.')

_PR = [('שיעור רווח נקי', pc(RT['nm'][0]), pc(RT['nm'][1])), ('תשואה על הנכסים', pc(RT['roa'][0]), pc(RT['roa'][1])), ('תשואה על ההון', pc(RT['roe'][0]), pc(RT['roe'][1])),
       ('מחזור הנכסים', f2(RT['at'][0]), f2(RT['at'][1])), ('מכפיל ההון', f2(RT['em'][0]), f2(RT['em'][1]))]
MC1('m-p1', 'רווחיות, שאלה 1 מתוך 3', 'למה התשואה על ההון של נועה גבוהה מהתשואה על הנכסים?',
    ['כי חלק מהנכסים ממומן בחוב: כל שקל של הבעלים ״מחזיק״ יותר משקל של נכסים', 'כי ההון גדול מהנכסים', 'כי הרווח הנקי גדול מהרווח התפעולי', 'זה מקרי'], 0,
    'הנכסים, 337,600, גדולים מההון, 295,600, כי 42,000 מומנו בחוב. אותו רווח מתחלק בבסיס קטן יותר, ולכן התשואה על ההון גבוהה יותר. זה מכפיל ההון: 1.14.', foot=FOOT, side=_side(_PR, {1: (0, 'k1'), 2: (0, 'k1'), 4: (0, 'k2')}), toon=('lever', 'אותו רווח, מכנה אחר.'))
MC1('m-p2', 'רווחיות, שאלה 2 מתוך 3', 'לפי פירוק דופונט, איזה גורם עלה מ-2026 ל-2027?',
    ['שיעור הרווח הנקי, מ-18.3% ל-20.5%', 'מחזור הנכסים', 'מכפיל ההון', 'כל שלושת הגורמים'], 0,
    'רק שיעור הרווח הנקי עלה. מחזור הנכסים ירד מ-2.28 ל-1.78, ומכפיל ההון מ-1.28 ל-1.14. שני אלה גברו, והתשואה על ההון ירדה.', foot=FOOT, side=_side(_PR, {0: (0, 'k2'), 3: (0, 'k3'), 4: (0, 'k3')}), toon=('mag', 'עברו גורם אחר גורם: עלה או ירד?'))
MC1('m-p3', 'רווחיות, שאלה 3 מתוך 3', 'נועה רוצה להחזיר את התשואה על ההון למעלה. מה מהבאים יעשה את זה, לפי דופונט?',
    ['להשקיע את המזומן שבקופה בסניף השני, שיגדיל את המכירות', 'להשאיר עוד מזומן בקופה', 'להחזיר את כל ההלוואה', 'להעלות את שכר הדירה'], 0,
    'מזומן שעובר לסניף שמוכר קפה מגדיל את המכירות בלי להגדיל את סך הנכסים, ולכן מחזור הנכסים עולה. השארת מזומן או החזרת חוב מורידות את מחזור הנכסים או את מכפיל ההון.', foot=FOOT, side=_side(_PR), toon=('coins', 'איזה גורם אפשר להזיז?'))
TOOLCARD('k-prof', 'כרטיס כלי: רווחיות', 'כמה רווח מניב כל שקל של נכסים ושל הבעלים, ולמה זה משתנה?',
         FL3([('רווח נקי', 'סך הנכסים', 'ROA'), ('רווח נקי', 'הון עצמי', 'ROE'), ('פתיחה ועוד סגירה', '2', 'יתרה ממוצעת')]),
         [('תשואה על הנכסים', pc(RT['roa'][0]), pc(RT['roa'][1])), ('תשואה על ההון', pc(RT['roe'][0]), pc(RT['roe'][1])), ('מחזור הנכסים', f2(RT['at'][0]), f2(RT['at'][1]))],
         'הרווח מכל שקל של מכירות עלה, אבל המזומן שהצטבר והחוב שירד הורידו את התשואה על ההון.',
         'רווח של שנה חלקי יתרה ביום אחד: בסוף שנה של צמיחה זה מקטין את התשואה. ותמיד משווים שנים באותה שיטה.', toon=('sleep', 'מזומן שישן מוריד תשואה.'))

