opener(7, 'יחסי שוק: כשהמניה נסחרת בבורסה', 'שאלת החלק: כמה משקיע משלם בבורסה על כל שקל של רווח?',
       ['חברה ציבורית לדוגמה: פולי זהב בע״מ', 'יחס ראשון: רווח למניה', 'יחס שני: מכפיל רווח', 'עוד שלושה: תשואת דיבידנד, שיעור חלוקה, מחיר לערך בספרים', 'בגיליון, ושתי שאלות'], 10, art=('market', 'מה שווה מניה?'))

PZ = dict(ni=(10_000_000, 12_000_000), sh=(10_000_000, 10_000_000), px=(14, 18), dv=(4_000_000, 6_000_000), eq=(52_000_000, 60_000_000))
_eps = tuple(PZ['ni'][y] / PZ['sh'][y] for y in (0, 1))
assert _eps == (1.0, 1.2) and f1(PZ['px'][1] / _eps[1]) == '15.0' and pc(PZ['dv'][1] / PZ['sh'][1] / PZ['px'][1]) == '3.3%'
_pzs = 'פולי זהב בע״מ, רשת בתי קפה (חברה שהומצאה להמחשה), נסחרת בבורסה. ב-2027: רווח נקי 12 מיליון ש״ח, 10 מיליון מניות, מחיר מניה 18 ש״ח, דיבידנד של 6 מיליון ש״ח, והון עצמי של 60 מיליון ש״ח.'
